    body=f"<div class=hero><div><h1>Profil</h1><div class=muted>Dane konta, bezpieczeństwo i wygląd dziennika.</div></div></div><div class='grid'><div class='card col6'><h3>Dane konta</h3><p><b>Imię i nazwisko:</b> {esc(u['full_name'])}</p><p><b>Login:</b> {esc(u['username'])}</p><p><b>Rola:</b> {esc(u['role'])}</p><p><b>E-mail:</b> {esc(u['email'])}</p><p><b>Informacja:</b> {esc(u['info'] or '—')}</p></div><div class='card col6'><h3>Zmiana hasła</h3><form class=form method=post action=/profile/password><input type=password name=current_password placeholder='Obecne hasło' required><input type=password name=new_password placeholder='Nowe hasło' minlength=4 required><input type=password name=confirm_password placeholder='Powtórz nowe hasło' minlength=4 required><button class=btn>Zmień hasło</button></form></div><div class='card col12'><h3>Kolor dziennika</h3><p class=muted>Wybierz jeden z trzech kwadratów. Ustawienie jest zapisywane na Twoim koncie.</p><div class=theme-picker>{choices}</div></div></div>"
